"""docich#5045: an unverified recovery must settle from the later balance.

An abandoned recovery whose payment state could not be confirmed keeps the
recruit/cards/castle hold for the rest of the month (fail-closed, #4989).
The held state itself is the receipt: while it is frozen, every other paid
screen stays closed or recorded, so the readable balance - minus the spends
the ledger can attribute - still answers the question. A remainder of zero
proves the attempt unpaid; a remainder matching the recorded quote proves
it paid. Anything else stays unverified.
"""
from pathlib import Path
import sys
sys.path.insert(0, str(Path(__file__).resolve().parents[2] / "src"))

from docich.hanjuku_speedrun import hanjuku_policy as p
from docich.hanjuku_speedrun.hanjuku.flows import month as month_flow
from docich.hanjuku_speedrun.hanjuku_screen import parse, Screen
from .test_hanjuku_chart_bot import _short_recruit_memory, month_canvas


def _held_memory(gold_before=9949, **shop_fields):
    """The #4980 incident shape: short roster, real castle waiting, and an
    abandoned egg recovery whose receipt was kept at the 'unverified' mark."""
    mem = _short_recruit_memory()
    for key, count in (('country_general_count', 2), ('country_soldier_count', 70)):
        mem[key] = {'scope': [1, '1-7'], 'identity': None,
                    'tick': mem['tick'], 'count': count}
    mem['captured'] = ['ジョンリギ']
    mem['garrison'] = {'アルマムーン': ['どうし', 'ゼウス'], 'ジョンリギ': ['ココット']}
    mem['shop'] = {'key': '1-7', 'items': [], 'merchant_done': True,
                   'soldiers': 0, 'soldiers_done': True, 'gold_start': gold_before,
                   'egg': 'unverified', 'egg_before_recruit': True,
                   'egg_receipt': {'before': gold_before, 'cost': 50, 'bought': 0,
                                   'refill_status': None, 'upgrades': 0,
                                   'recruit': 'deferred_egg'},
                   'recruit': 'deferred_egg', 'recruit_reserve': 0,
                   'cards_held': 'recruit_pending', 'chikujou_held': True,
                   'chikujou': 'skipped', 'reserve': 0, 'hero_repair_reserve': 0}
    mem['shop'].update(shop_fields)
    return mem


def test_an_unchanged_balance_settles_unpaid_and_releases_the_held_castle():
    """rest == 0: nothing was ever charged, so the recovery ends unpaid
    ('skipped') and the held cards/castle are released."""
    mem = _held_memory()
    actions = month_flow.month_step(parse(month_canvas(9949, on='ちくじょう')), mem)
    shop = mem['shop']
    assert shop['egg'] == 'skipped'
    assert shop['egg_recheck_settled'] is True
    assert 'cards_held' not in shop
    assert shop['chikujou'] == 'opened'
    assert mem['month_sub']['kind'] == 'chikujou'
    assert actions == [p.pad('a')]
    rec = next(r for r in mem['_records'] if r.get('decision') == 'egg_unverified_settled')
    assert rec['observed_metric']['settled'] == 'skipped'
    assert any(r.get('decision') == 'month_cards_released' for r in mem['_records'])


def test_a_matching_debit_settles_done_and_releases_the_hold():
    """rest == quoted_cost: the fee is the only debit left - the same
    receipt standard _finish_month_sub uses for a paid recovery."""
    mem = _held_memory()
    month_flow.month_step(parse(month_canvas(9899, on='ちくじょう')), mem)
    shop = mem['shop']
    assert shop['egg'] == 'done'
    assert shop['egg_recheck_settled'] is True
    rec = next(r for r in mem['_records'] if r.get('decision') == 'egg_unverified_settled')
    assert rec['observed_metric']['settled'] == 'done'


def test_a_post_mark_refill_is_subtracted_before_settling():
    """A refill paid after the mark (1G per soldier) is subtracted: the
    remaining delta still isolates the recovery fee."""
    mem = _held_memory(soldier_receipt={'status': 'paid', 'qty': 30})
    month_flow.month_step(parse(month_canvas(9869, on='ちくじょう')), mem)  # 9949 - 30 - 50
    assert mem['shop']['egg'] == 'done'
    rec = next(r for r in mem['_records'] if r.get('decision') == 'egg_unverified_settled')
    assert rec['observed_metric']['others'] == 30


def test_a_refill_explaining_the_whole_delta_settles_unpaid():
    """A post-mark refill equal to the whole delta leaves rest == 0: the
    recovery provably never paid."""
    mem = _held_memory(soldier_receipt={'status': 'paid', 'qty': 50})
    month_flow.month_step(parse(month_canvas(9899, on='しょうにん')), mem)
    assert mem['shop']['egg'] == 'skipped'


def test_an_ambiguous_delta_keeps_the_unverified_hold():
    """A remainder matching neither zero nor the quote cannot be attributed;
    the fail-closed hold stays for the rest of the month."""
    mem = _held_memory()
    month_flow.month_step(parse(month_canvas(9800, on='しょうにん')), mem)
    shop = mem['shop']
    assert shop['egg'] == 'unverified'
    assert 'egg_recheck_settled' not in shop
    assert shop['recruit'] == 'deferred_egg'
    assert shop['cards_held'] == 'recruit_pending'
    assert shop['chikujou'] == 'skipped'
    assert 'month_sub' not in mem
    assert not any(r.get('decision') == 'egg_unverified_settled' for r in mem['_records'])


def test_an_unverified_refill_keeps_the_delta_unverified():
    """A post-mark refill whose spend was never read shares the delta."""
    mem = _held_memory(soldier_receipt={'status': 'unverified', 'qty': 30})
    month_flow.month_step(parse(month_canvas(9899, on='しょうにん')), mem)
    assert mem['shop']['egg'] == 'unverified'
    assert 'egg_recheck_settled' not in mem['shop']


