def test_a_settled_skip_is_never_repended_or_repaid():
    """The unpaid proof releases the hold but must not reopen the recovery:
    egg_recheck_settled blocks every same-month re-pending path."""
    mem = _held_memory()
    for _ in range(4):
        month_flow.month_step(parse(month_canvas(9949, on='しょうぐんぼしゅう')), mem)
    shop = mem['shop']
    assert shop['egg'] == 'skipped'          # settled once, never repended
    assert (mem.get('month_sub') or {}).get('kind') != 'egg'
    assert shop['recruit'] == 'deferred_egg'  # no recruitment fee was paid


def test_settled_flag_blocks_the_repend_gate():
    mem = _short_recruit_memory()
    shop = {'key': '1-7', 'egg': 'skipped', 'egg_recheck_settled': True,
            'recruit': 'check'}
    p._prepare_recruit_egg_check(mem, shop, 180)
    assert shop['egg'] == 'skipped'
    without_flag = {'key': '1-7', 'egg': 'skipped', 'recruit': 'check'}
    p._prepare_recruit_egg_check(mem, without_flag, 180)
    assert without_flag['egg'] == 'pending'


def test_the_lost_paid_sub_keeps_its_receipt_for_later_settling():
    """_finish_month_sub records the unverified mark's payment expectation."""
    mem = _short_recruit_memory()
    mem['shop'] = {'key': '1-7', 'egg': 'opened', 'recruit': 'check'}
    mem['month_sub'] = {'kind': 'egg', 'gold_before': 200, 'quoted_cost': 50,
                        'full_selected': True, 'left_menu': True, 'key': '1-7',
                        'stage': 'recovering'}
    screen = Screen([], None, '', header={'year': 1, 'month': 7, 'gold': 200})
    assert month_flow._finish_month_sub(screen, mem, mem['shop'])
    assert mem['shop']['egg'] == 'unverified'
    assert mem['shop']['egg_receipt'] == {'before': 200, 'cost': 50, 'bought': 0,
                                        'refill_status': None, 'upgrades': 0,
                                        'recruit': 'check'}


def test_an_interrupted_sub_keeps_no_receipt():
    """A payment_interrupted sub's balance delta is never evidence."""
    mem = _short_recruit_memory()
    mem['shop'] = {'key': '1-7', 'egg': 'opened', 'recruit': 'check'}
    mem['month_sub'] = {'kind': 'egg', 'gold_before': 200, 'quoted_cost': 50,
                        'full_selected': True, 'left_menu': True, 'key': '1-7',
                        'stage': 'recovering', 'payment_interrupted': True}
    screen = Screen([], None, '', header={'year': 1, 'month': 7, 'gold': 200})
    assert month_flow._finish_month_sub(screen, mem, mem['shop'])
    assert mem['shop']['egg'] == 'unverified'
    assert 'egg_receipt' not in mem['shop']
